{
  "js": "import {makeCalendarMonth,shiftCalendarMonth,chooseCalendarDate} from './calendar-model.js';
import {parseStayDate,countNights,isBookableRange} from './dates.js';
import {renderCalendarMonths} from './calendar-renderer.js';

export function installDateCalendar({dialog,today}) {
  let currentCallback = null;
  let currentDraft = { start: null, end: null, error: null };
  let currentShownMonth = today;
  let currentOpener = null;
  let lastFocusedDate = null;

  const monthsContainer = dialog.querySelector('#calendar-months');
  const cancelBtn = dialog.querySelector('#calendar-cancel');
  const applyBtn = dialog.querySelector('#calendar-apply');
  const prevBtn = dialog.querySelector('#calendar-previous');
  const nextBtn = dialog.querySelector('#calendar-next');
  const selectionP = dialog.querySelector('#calendar-selection');
  const errorP = dialog.querySelector('#calendar-error');

  function updateSelectionSummary() {
    const { start, end, error } = currentDraft;
    if (error) {
      errorP.textContent = error;
      selectionP.textContent = '';
      return;
    }
    if (!start) {
      selectionP.textContent = '체크인 날짜를 선택해 주세요';
      errorP.textContent = '';
    } else if (!end) {
      selectionP.textContent = '체크아웃 날짜를 선택해 주세요';
      errorP.textContent = '';
    } else {
      const nights = countNights(start, end);
      selectionP.textContent = `${start} ~ ${end} (${nights}박)`;
      errorP.textContent = '';
    }
  }

  function render() {
    const draft = { ...currentDraft };
    renderCalendarMonths(monthsContainer, {
      month: currentShownMonth,
      today: today,
      draft: draft,
      focusDate: lastFocusedDate
    });
    updateSelectionSummary();
    const focused = document.activeElement;
    if (focused && focused.dataset.date) {
      lastFocusedDate = focused.dataset.date;
    } else {
      lastFocusedDate = null;
    }
  }

  function handleDateClick(dateStr) {
    try {
      const fresh = chooseCalendarDate(currentDraft, dateStr, today);
      currentDraft = fresh;
      lastFocusedDate = dateStr;
      render();
    } catch (e) {
      currentDraft.error = e.message;
      render();
    }
  }

  function handleApply() {
    if (currentDraft.start && currentDraft.end && !currentDraft.error) {
      if (currentCallback) {
        currentCallback({ start: currentDraft.start, end: currentDraft.end });
      }
      dismiss();
    }
  }

  function handleCancel() {
    dismiss();
  }

  function handlePrev() {
    const newMonth = shiftCalendarMonth(currentShownMonth, -1);
    if (newMonth) {
      currentShownMonth = newMonth;
      render();
    }
  }

  function handleNext() {
    if (currentShownMonth < '2099-12') {
      currentShownMonth = shiftCalendarMonth(currentShownMonth, 1);
      render();
    }
  }

  function handleKeyDown(e) {
    if (!currentDraft.start && !currentDraft.end) return;
    if (['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End','PageUp','PageDown'].includes(e.key)) {
      e.preventDefault();
      let newDate = null;
      if (e.key === 'ArrowLeft') newDate = shiftCalendarMonth(lastFocusedDate, -1);
      if (e.key === 'ArrowRight') newDate = shiftCalendarMonth(lastFocusedDate, 1);
      if (e.key === 'ArrowUp') newDate = shiftCalendarMonth(lastFocusedDate, -7);
      if (e.key === 'ArrowDown') newDate = shiftCalendarMonth(lastFocusedDate, 7);
      if (e.key === 'Home') {
        const d = new Date(lastFocusedDate + 'T00:00:00Z');
        const day = d.getUTCDay();
        newDate = shiftCalendarMonth(lastFocusedDate, -day);
      }
      if (e.key === 'End') {
        const d = new Date(lastFocusedDate + 'T00:00:00Z');
        const day = d.getUTCDay();
        newDate = shiftCalendarMonth(lastFocusedDate, 6 - day);
      }
      if (e.key === 'PageUp') {
        const shift = e.shiftKey ? -12 : -1;
        const month = shiftCalendarMonth(lastFocusedDate, shift);
        if (month) {
          const targetMonthData = makeCalendarMonth(month, today);
          const daysInMonth = targetMonthData.days.length;
          const todayDate = new Date(today + 'T00:00:00Z');
          const todayDay = todayDate.getUTCDate();
          const clampedDay = Math.min(todayDay, daysInMonth);
          const targetDate = new Date(Date.UTC(todayDate.getUTCFullYear(), targetMonthData.month.getMonth(), clampedDay));
          newDate = targetDate.toISOString().split('T')[0];
        }
      }
      if (e.key === 'PageDown') {
        const shift = e.shiftKey ? 12 : 1;
        const month = shiftCalendarMonth(lastFocusedDate, shift);
        if (month) {
          const targetMonthData = makeCalendarMonth(month, today);
          const daysInMonth = targetMonthData.days.length;
          const todayDate = new Date(today + 'T00:00:00Z');
          const todayDay = todayDate.getUTCDate();
          const clampedDay = Math.min(todayDay, daysInMonth);
          const targetDate = new Date(Date.UTC(todayDate.getUTCFullYear(), targetMonthData.month.getMonth(), clampedDay));
          newDate = targetDate.toISOString().split('T')[0];
        }
      }
      if (newDate) {
        const newDateMs = parseStayDate(newDate);
        const todayMs = parseStayDate(today);
        if (newDateMs !== null && todayMs !== null && newDateMs >= todayMs) {
          const maxDateMs = parseStayDate('2099-12-31');
          if (newDateMs <= maxDateMs) {
            lastFocusedDate = newDate;
            const newMonth = newDate.substring(0, 7);
            if (newMonth !== currentShownMonth) {
              currentShownMonth = newMonth;
            }
            render();
          }
        }
      }
    }
  }

  function open({start, end}, onApply, opener) {
    currentCallback = onApply;
    currentOpener = opener;
    let initStart = null;
    let initEnd = null;
    if (start && end) {
      const sMs = parseStayDate(start);
      const eMs = parseStayDate(end);
      const tMs = parseStayDate(today);
      if (sMs !== null && eMs !== null && tMs !== null && sMs >= tMs && eMs > sMs) {
        const nights = countNights(start, end);
        if (nights >= 1 && nights <= 28) {
          initStart = start;
          initEnd = end;
        }
      }
    }
    currentDraft = { start: initStart, end: initEnd, error: null };
    currentShownMonth = initStart ? initStart.substring(0, 7) : today;
    lastFocusedDate = null;
    render();
    dialog.showModal();
  }

  function dismiss() {
    dialog.close();
    currentCallback = null;
    currentDraft = { start: null, end: null, error: null };
    currentShownMonth = today;
    lastFocusedDate = null;
    if (currentOpener && typeof currentOpener.focus === 'function') {
      currentOpener.focus();
    }
    currentOpener = null;
  }

  cancelBtn.addEventListener('click', handleCancel);
  applyBtn.addEventListener('click', handleApply);
  prevBtn.addEventListener('click', handlePrev);
  nextBtn.addEventListener('click', handleNext);
  dialog.addEventListener('keydown', handleKeyDown);
  dialog.addEventListener('close', () => {
    currentCallback = null;
    currentDraft = { start: null, end: null, error: null };
    currentShownMonth = today;
    lastFocusedDate = null;
  });

  return { open, dismiss };
}"
}

