  "js": "import {makeCalendarMonth,shiftCalendarMonth,chooseCalendarDate} from './calendar-model.js';
import {parseStayDate,countNights,isBookableRange} from './dates.js';
import {renderCalendarMonths} from './calendar-renderer.js';

export function installDateCalendar({dialog, today}) {
  let draft = { start: '', end: '', error: '' };
  let focusDate = '';
  let shownMonth = today.slice(0, 7);
  let callback = null;
  let opener = null;

  const monthsContainer = dialog.querySelector('#calendar-months');
  const applyBtn = dialog.querySelector('#calendar-apply');
  const prevBtn = dialog.querySelector('#calendar-previous');
  const nextBtn = dialog.querySelector('#calendar-next');
  const selectionP = dialog.querySelector('#calendar-selection');
  const errorP = dialog.querySelector('#calendar-error');

  function updateSummary() {
    if (!draft.start && !draft.end) {
      selectionP.textContent = '체크인 날짜를 선택해 주세요';
    } else if (draft.start && !draft.end) {
      selectionP.textContent = '체크아웃 날짜를 선택해 주세요';
    } else {
      const n = countNights(draft.start, draft.end);
      const s = draft.start.replace(/-/g, '.');
      const e = draft.end.replace(/-/g, '.');
      selectionP.textContent = `${s} ~ ${e} (${n}박)`;
    }
    if (draft.error) {
      errorP.textContent = draft.error;
    } else {
      errorP.textContent = '';
    }
  }

  function updateButtons() {
    const valid = isBookableRange(draft.start, draft.end, today);
    applyBtn.disabled = !valid;
    const todayMonth = today.slice(0, 7);
    prevBtn.disabled = shownMonth <= todayMonth;
    nextBtn.disabled = shownMonth >= '2099-12';
  }

  function render() {
    renderCalendarMonths(monthsContainer, {
      month: shownMonth,
      today: today,
      draft: draft,
      focusDate: focusDate
    });
    updateSummary();
    updateButtons();
    const btn = monthsContainer.querySelector(`button[data-date="${focusDate}"]`);
    if (btn) btn.focus();
  }

  function clearState() {
    draft = { start: '', end: '', error: '' };
    callback = null;
    opener = null;
  }

  function open({ start, end }, onApply, currentOpener) {
    const s = start || '';
    const e = end || '';
    const parsedS = parseStayDate(s);
    const parsedE = parseStayDate(e);

    if (parsedS !== null && parsedE !== null && isBookableRange(s, e, today)) {
      draft = { start: s, end: e, error: '' };
      shownMonth = s.slice(0, 7);
      focusDate = e;
    } else {
      draft = { start: '', end: '', error: '' };
      shownMonth = today.slice(0, 7);
      focusDate = '';
    }
    callback = onApply;
    opener = currentOpener;
    dialog.showModal();
    render();
  }

  function dismiss() {
    dialog.close();
    clearState();
  }

  function handleCancel() {
    dialog.close();
    if (opener && opener.isConnected) opener.focus();
    clearState();
  }

  dialog.addEventListener('close', () => {
    clearState();
  });

  prevBtn.addEventListener('click', () => {
    const m = shiftCalendarMonth(shownMonth, -1);
    if (m) {
      shownMonth = m;
      render();
    }
  });

  nextBtn.addEventListener('click', () => {
    const m = shiftCalendarMonth(shownMonth, 1);
    if (m) {
      shownMonth = m;
      render();
    }
  });

  applyBtn.addEventListener('click', () => {
    if (isBookableRange(draft.start, draft.end, today)) {
      callback({ start: draft.start, end: draft.end });
      dialog.close();
      if (opener && opener.isConnected) opener.focus();
      clearState();
    }
  });

  dialog.querySelector('#calendar-cancel').addEventListener('click', handleCancel);

  monthsContainer.addEventListener('click', (e) => {
    const btn = e.target.closest('button[data-date]');
    if (!btn) return;
    const date = btn.dataset.date;
    try {
      const newDraft = chooseCalendarDate(draft, date, today);
      draft = newDraft;
      focusDate = date;
      const m = date.slice(0, 7);
      if (m !== shownMonth) {
        shownMonth = m;
      }
      render();
    } catch (err) {
      // ignore invalid
    }
  });

  monthsContainer.addEventListener('keydown', (e) => {
    const btn = e.target.closest('button[data-date]');
    if (!btn || !btn.disabled) return;

    let d = new Date(btn.dataset.date + 'T00:00:00Z');
    let handled = false;

    if (e.key === 'ArrowLeft') { d.setUTCDate(d.getUTCDate() - 1); handled = true; }
    else if (e.key === 'ArrowRight') { d.setUTCDate(d.getUTCDate() + 1); handled = true; }
    else if (e.key === 'ArrowUp') { d.setUTCDate(d.getUTCDate() - 7); handled = true; }
    else if (e.key === 'ArrowDown') { d.setUTCDate(d.getUTCDate() + 7); handled = true; }
    else if (e.key === 'Home') { d.setUTCDate(d.getUTCDate() - d.getUTCDay()); handled = true; }
    else if (e.key === 'End') { d.setUTCDate(d.getUTCDate() + (6 - d.getUTCDay())); handled = true; }
    else if (e.key === 'PageUp') { d.setMonth(d.getUTCMonth() - 1); handled = true; }
    else if (e.key === 'PageDown') { d.setMonth(d.getUTCMonth() + 1); handled = true; }
    else if (e.key === 'Shift+PageUp') { d.setMonth(d.getUTCMonth() - 12); handled = true; }
    else if (e.key === 'Shift+PageDown') { d.setMonth(d.getUTCMonth() + 12); handled = true; }

    if (handled) {
      e.preventDefault();
      const iso = d.toISOString().slice(0, 10);
      if (iso < today.slice(0, 10)) return;
      if (iso > '2099-12-31') return;

      focusDate = iso;
      const m = iso.slice(0, 7);
      if (m !== shownMonth) {
        shownMonth = m;
      }
      render();
    }
  });

  return { open, dismiss };
}"
}

