export function resolveCalendarFocus(date, key, shift, today) {
  if (key === "ArrowLeft") return clampDate(toUTCDate(date) - 86400000, today, "2099-12-31");
  if (key === "ArrowRight") return clampDate(toUTCDate(date) + 86400000, today, "2099-12-31");
