    const m = shiftCalendarMonth(date.substring(0, 7), shift ? 12 : 1);
    if (m === null) return "2099-12-31";
    const days = makeCalendarMonth(m, today).days.length;
    const d = Math.min(toUTCDate(date).getUTCDate(), days);
    return toISO(clampDate(new Date(Date.UTC(toUTCDate(date).getUTCFullYear(), toUTCDate(date).getUTCMonth(), d)), today, "2099-12-31"));
  }
  return null;
