function toUTCDate(iso) {
  const [y, m, d] = iso.split("-").map(Number);
  return new Date(Date.UTC(y, m - 1, d));
}

function clampDate(d, min, max) {
  const t = Date.now();
  const minDate = new Date(Date.UTC(...min.split("-").map(Number)));
  const maxDate = new Date(Date.UTC(...max.split("-").map(Number)));
  if (d < minDate) return toISO(minDate);
  if (d > maxDate) return toISO(maxDate);
  return toISO(d);
}

