{"body":"export function renderCalendarMonths(container, { month, today, draft, focusDate }) {
  const { makeCalendarMonth, shiftCalendarMonth } = window.__DEPS__.calendarModel;
  const monthData = makeCalendarMonth(month, today);
  const nextMonthStr = shiftCalendarMonth(month, 1);

  container.replaceChildren();

  const monthSections = [];
  const allEnabledDates = new Set();
  const allDayButtons = [];

  // Process the primary month
  const section1 = document.createElement('section');
  section1.className = 'calendar-month';

  const caption1 = document.createElement('caption');
  caption1.className = 'calendar-month-title';
  caption1.textContent = monthData.label;
  section1.appendChild(caption1);

  const table1 = document.createElement('table');
  const thead1 = document.createElement('thead');
  const tr1 = document.createElement('tr');
  ['일', '월', '화', '수', '목', '금', '토'].forEach(day => {
    const th = document.createElement('th');
    th.setAttribute('scope', 'col');
    th.textContent = day;
    tr1.appendChild(th);
  });
  thead1.appendChild(tr1);
  table1.appendChild(thead1);

  const tbody1 = document.createElement('tbody');
  let currentRow = document.createElement('tr');

  // Leading padding
  for (let i = 0; i < monthData.leading; i++) {
    const td = document.createElement('td');
    td.setAttribute('aria-hidden', 'true');
    currentRow.appendChild(td);
  }

  monthData.days.forEach(day => {
    if (currentRow.children.length === 7) {
      tbody1.appendChild(currentRow);
      currentRow = document.createElement('tr');
    }

    const td = document.createElement('td');
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'calendar-day';
    btn.dataset.date = day.date;
    btn.dataset.number = String(day.day);
    btn.disabled = day.disabled;
    btn.textContent = String(day.day);
    btn.setAttribute('aria-pressed', 'false');

    // Range logic
    let rangeType = null;
    if (draft.start && draft.end) {
      if (day.date === draft.start) {
        rangeType = 'start';
        btn.dataset.selected = 'start';
        btn.textContent += ' 체크인';
      } else if (day.date === draft.end) {
        rangeType = 'end';
        btn.dataset.selected = 'end';
        btn.textContent += ' 체크아웃';
      } else if (day.date > draft.start && day.date < draft.end) {
        rangeType = 'middle';
      }
    } else if (draft.start && !draft.end) {
       if (day.date === draft.start) rangeType = 'start';
    }

    if (rangeType) {
      td.dataset.range = rangeType;
      btn.setAttribute('aria-pressed', 'true');
    }

    if (day.date === today) {
      btn.setAttribute('aria-current', 'date');
    }

    // Accessibility label
    const dateObj = new Date(day.date);
    const weekDays = ['일요일', '월요일', '화요일', '수요일', '목요일', '금요일', '토요일'];
    btn.setAttribute('aria-label', `${dateObj.getFullYear()}년 ${dateObj.getMonth() + 1}월 ${dateObj.getDate()}일 ${weekDays[dateObj.getDay()]}`);

    btn.addEventListener('click', () => {
      // Placeholder for event wiring
      console.log('Day clicked:', day.date);
    });

    td.appendChild(btn);
    currentRow.appendChild(td);
    if (!day.disabled) allEnabledDates.add(day.date);
    allDayButtons.push(btn);
  });

  // Trailing padding
  while (currentRow.children.length < 7) {
    const td = document.createElement('td');
    td.setAttribute('aria-hidden', 'true');
    currentRow.appendChild(td);
  }
  tbody1.appendChild(currentRow);
  table1.appendChild(tbody1);
  section1.appendChild(table1);
  monthSections.push(section1);

  // Process next month
  if (nextMonthStr) {
    const monthData2 = makeCalendarMonth(nextMonthStr, today);
    const section2 = document.createElement('section');
    section2.className = 'calendar-month';

    const caption2 = document.createElement('caption');
    caption2.className = 'calendar-month-title';
    caption2.textContent = monthData2.label;
    section2.appendChild(caption2);

    const table2 = document.createElement('table');
    const thead2 = document.createElement('thead');
    const tr2 = document.createElement('tr');
    ['일', '월', '화', '수', '목', '금', '토'].forEach(day => {
      const th = document.createElement('th');
      th.setAttribute('scope', 'col');
      th.textContent = day;
      tr2.appendChild(th);
    });
    thead2.appendChild(tr2);
    table2.appendChild(thead2);

    const tbody2 = document.createElement('tbody');
    let currentRow2 = document.createElement('tr');

    for (let i = 0; i < monthData2.leading; i++) {
      const td = document.createElement('td');
      td.setAttribute('aria-hidden', 'true');
      currentRow2.appendChild(td);
    }

    monthData2.days.forEach(day => {
      if (currentRow2.children.length === 7) {
        tbody2.appendChild(currentRow2);
        currentRow2 = document.createElement('tr');
      }

      const td = document.createElement('td');
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'calendar-day';
      btn.dataset.date = day.date;
      btn.dataset.number = String(day.day);
      btn.disabled = day.disabled;
      btn.textContent = String(day.day);
      btn.setAttribute('aria-pressed', 'false');

      let rangeType = null;
      if (draft.start && draft.end) {
        if (day.date === draft.start) {
          rangeType = 'start';
          btn.dataset.selected = 'start';
          btn.textContent += ' 체크인';
        } else if (day.date === draft.end) {
          rangeType = 'end';
          btn.dataset.selected = 'end';
          btn.textContent += ' 체크아웃';
        } else if (day.date > draft.start && day.date < draft.end) {
          rangeType = 'middle';
        }
      } else if (draft.start && !draft.end) {
         if (day.date === draft.start) rangeType = 'start';
      }

      if (rangeType) {
        td.dataset.range = rangeType;
        btn.setAttribute('aria-pressed', 'true');
      }

      if (day.date === today) {
        btn.setAttribute('aria-current', 'date');
      }

      const dateObj = new Date(day.date);
      const weekDays = ['일요일', '월요일', '화요일', '수요일', '목요일', '금요일', '토요일'];
      btn.setAttribute('aria-label', `${dateObj.getFullYear()}년 ${dateObj.getMonth() + 1}월 ${dateObj.getDate()}일 ${weekDays[dateObj.getDay()]}`);

      btn.addEventListener('click', () => {
        console.log('Day clicked:', day.date);
      });

      td.appendChild(btn);
      currentRow2.appendChild(td);
      if (!day.disabled) allEnabledDates.add(day.date);
      allDayButtons.push(btn);
    });

    while (currentRow2.children.length < 7) {
      const td = document.createElement('td');
      td.setAttribute('aria-hidden', 'true');
      currentRow2.appendChild(td);
    }
    tbody2.appendChild(currentRow2);
    table2.appendChild(tbody2);
    section2.appendChild(table2);
    monthSections.push(section2);
  }

  monthSections.forEach(sec => container.appendChild(sec));

  // Focus management
  let focusTarget = null;
  if (focusDate && allEnabledDates.has(focusDate)) {
    focusTarget = container.querySelector(`button[data-date="${focusDate}"]`);
  }
  if (!focusTarget && draft.start && allEnabledDates.has(draft.start)) {
    focusTarget = container.querySelector(`button[data-date="${draft.start}"]`);
  }
  if (!focusTarget) {
    focusTarget = allDayButtons.find(btn => !btn.disabled);
  }

  allDayButtons.forEach(btn => {
    btn.tabIndex = btn === focusTarget ? 0 : -1;
  });
}"}

